def get_divisors(n: int) -> List[int]:
    """Returns a sorted list of all positive divisors of n."""
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n: int) -> int:
    """Calculates the sum of all positive divisors of n (sigma(n))."""
    divs = get_divisors(n)
    return sum(divs)

