import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def solve_backtracking(m, divisors):
    n = len(divisors)

    # Pre-check: Total sum must be a perfect square
    total_sum = sum(divisors)
    if not is_perfect_square(total_sum):
        return False

    # Filter out squares for the starting element a1, although in this specific case (m=119), only 1 works.
    square_divisors = [d for d in divisors if is_perfect_square(d)]

    def backtrack(current_path, used_divisors, current_sum):
        # Base case: Sequence is complete
        if len(current_path) == n:
            # We already checked the total sum, so this condition guarantees success.
            return True

        # Check if the current sum is a perfect square (This check should technically happen *after* adding the element, 
        # but since we start with a square sum, we only need to check when adding the next element.)

        for d in divisors:
            if d not in used_divisors:
                next_sum = current_sum + d

                if is_perfect_square(next_sum):
                    # Recursive step
                    if backtrack(current_path + [d], used_divisors | {d}, next_sum):
                        return True
        return False

    # Start the search only from possible initial square divisors
    for a1 in square_divisors:
        # S1 = a1 is guaranteed to be a square
        if backtrack([a1], {a1}, a1):
            return True

    return False

